input.content:
:root {
    --paper: #f6f2e9;
    --paper-deep: #efe9da;
    --card: #fbf8f0;
    --ink: #1d1a14;
    --ink-soft: #5e5749;
    --ink-faint: #8d8574;
    --line: #d9d1bf;
    --line-dark: #1d1a14;
    --accent: #b14e28;
    --teal: #3c6e64;
}

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

html {
    font-size: 16px;
    scroll-behavior: smooth;
}

body {
    font-family: 'Anthropic Mono', monospace;
    background: var(--paper);
    color: var(--ink);
    line-height: 1.6;
    min-height: 100vh;
}

::selection {
    background: #b14e2826;
    color: var(--ink);
}

/* ── Motion ── */
@keyframes rise {
    from { opacity: 0; transform: translateY(18px); }
    to   { opacity: 1; transform: translateY(0); }
}

@keyframes line-draw {
    from { transform: scaleX(0); }
    to   { transform: scaleX(1); }
}

.reveal {
    opacity: 0;
    transform: translateY(20px);
    transition: opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1),
                transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
    transition-delay: var(--d, 0s);
}

.reveal.in {
    opacity: 1;
    transform: none;
}

@media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
    .reveal { opacity: 1; transform: none; }
}

/* ── Top bar ── */
.topbar {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 1rem;
    padding: 1.1rem 2rem;
    border-bottom: 1px solid var(--line);
    font-size: 0.68rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--ink-soft);
}

.topbar strong { color: var(--ink); font-weight: normal; }
.topbar .topbar-right { color: var(--ink-faint); }

/* ── Hero ── */
.hero {
    max-width: 1100px;
    margin: 0 auto;
    padding: 5rem 2rem 3.5rem;
}

.hero-eyebrow {
    font-size: 0.7rem;
    letter-spacing: 0.35em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 1.5rem;
}

.hero h1 {
    font-family: 'Anthropic Serif', serif;
    font-weight: bold;
    font-size: clamp(2.5rem, 7vw, 4.6rem);
    line-height: 1.04;
    letter-spacing: -0.02em;
    max-width: 13em;
}

.hero h1 .highlight  { color: var(--accent); }
.hero h1 .highlight2 { color: var(--teal); font-style: italic; }

.hero-lede {
    font-size: 0.95rem;
    color: var(--ink-soft);
    max-width: 560px;
    margin-top: 1.75rem;
    line-height: 1.85;
}

.hero-lede strong { color: var(--ink); font-weight: normal; border-bottom: 1px solid var(--accent); }

.hero-eyebrow,
.hero h1,
.hero-lede,
.hero-stats {
    opacity: 0;
    animation: rise 0.9s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.hero h1     { animation-delay: 0.1s; }
.hero-lede   { animation-delay: 0.24s; }
.hero-stats  { animation-delay: 0.4s; }

.hero-stats {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    margin-top: 3.25rem;
    border-top: 1px solid var(--line-dark);
    border-bottom: 1px solid var(--line);
}

.stat {
    padding: 1.4rem 1.5rem 1.4rem 0;
    border-left: 1px solid var(--line);
    padding-left: 1.5rem;
}

.stat:first-child { border-left: none; padding-left: 0; }

.stat-num {
    font-family: 'Anthropic Serif', serif;
    font-weight: bold;
    font-size: 2.1rem;
    line-height: 1.1;
    color: var(--ink);
}

.stat-num.accent { color: var(--teal); }

.stat-label {
    font-size: 0.65rem;
    color: var(--ink-faint);
    text-transform: uppercase;
    letter-spacing: 0.15em;
    margin-top: 0.35rem;
}

/* ── Section scaffolding ── */
.section {
    padding: 4.5rem 2rem;
    max-width: 1100px;
    margin: 0 auto;
}

.section-head {
    display: flex;
    align-items: baseline;
    gap: 1.25rem;
    border-bottom: 1px solid var(--line-dark);
    padding-bottom: 1rem;
    margin-bottom: 2.25rem;
}

.section-no {
    font-size: 0.7rem;
    color: var(--accent);
    letter-spacing: 0.2em;
    white-space: nowrap;
}

.section-label {
    font-size: 0.68rem;
    letter-spacing: 0.28em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 0.6rem;
}

.section h2 {
    font-family: 'Anthropic Serif', serif;
    font-weight: bold;
    font-size: clamp(1.6rem, 3.5vw, 2.5rem);
    line-height: 1.15;
}

.section-sub {
    color: var(--ink-soft);
    font-size: 0.88rem;
    max-width: 560px;
    margin: 0.9rem 0 2.25rem;
    line-height: 1.75;
}

/* ── Mission ── */
.mission-band {
    background: var(--paper-deep);
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
}

.mission {
    max-width: 1100px;
    margin: 0 auto;
    padding: 4rem 2rem;
    display: grid;
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
    gap: 3rem;
    align-items: start;
}

.mission blockquote {
    font-family: 'Anthropic Serif', serif;
    font-size: clamp(1.3rem, 2.6vw, 1.9rem);
    line-height: 1.35;
    color: var(--ink);
    font-style: italic;
}

.mission blockquote::before { content: '\201C'; color: var(--accent); }
.mission blockquote::after  { content: '\201D'; color: var(--accent); }

.accent-line {
    width: 56px;
    height: 2px;
    background: var(--accent);
    margin: 1.4rem 0 0;
    transform-origin: left;
}

.reveal.in .accent-line,
.accent-line.in {
    animation: line-draw 0.8s cubic-bezier(0.22, 1, 0.36, 1) 0.2s backwards;
}

.mission-body {
    color: var(--ink-soft);
    font-size: 0.85rem;
    line-height: 1.8;
}

.mission-body strong { color: var(--ink); font-weight: normal; border-bottom: 1px solid var(--accent); }

.mission-goals {
    margin-top: 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
}

.mission-goal {
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 0.6rem;
    padding: 0.75rem 1rem;
    border: 1px solid var(--line);
    background: var(--card);
    font-size: 0.78rem;
    color: var(--ink-soft);
    transition: border-color 0.35s ease, transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.mission-goal:hover {
    border-color: var(--ink);
    transform: translateX(4px);
}

.mission-goal strong {
    font-family: 'Anthropic Serif', serif;
    font-weight: bold;
    font-size: 0.95rem;
    color: var(--ink);
}

.mission-goal .verdict-bad  { color: var(--accent); }
.mission-goal .verdict-good { color: var(--teal); }

/* ── Featured (lead developer) ── */
.featured-card {
    display: flex;
    align-items: center;
    gap: 1.75rem;
    padding: 1.75rem 2rem;
    margin-bottom: 2.5rem;
    background: var(--card);
    border: 1px solid var(--ink);
    box-shadow: 6px 6px 0 var(--line);
    transition: box-shadow 0.35s ease, transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.featured-card:hover {
    transform: translate(-2px, -2px);
    box-shadow: 9px 9px 0 var(--line);
}

.featured-card .person-avatar {
    width: 88px;
    height: 88px;
    filter: none;
    border: 1px solid var(--ink);
}

.featured-tag {
    display: inline-block;
    font-size: 0.62rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--paper);
    background: var(--accent);
    padding: 0.3rem 0.7rem;
    margin-bottom: 0.6rem;
}

.featured-name {
    font-family: 'Anthropic Serif', serif;
    font-weight: bold;
    font-size: 1.5rem;
    line-height: 1.2;
}

.featured-handle {
    font-size: 0.72rem;
    color: var(--ink-faint);
    margin-top: 0.15rem;
}

.featured-blurb {
    font-size: 0.8rem;
    color: var(--ink-soft);
    margin-top: 0.7rem;
    max-width: 540px;
    line-height: 1.7;
}

/* ── People grid ── */
.people-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 1px;
    background: var(--line);
    border: 1px solid var(--line);
}

.person-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 1.4rem 0.75rem 1.2rem;
    background: var(--card);
    transition: background-color 0.35s ease;
}

.person-card:hover { background: #fffdf6; }

.person-avatar {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    object-fit: cover;
    border: 1px solid var(--line);
    margin-bottom: 0.7rem;
    filter: grayscale(1) contrast(1.05);
    transition: filter 0.4s ease, transform 0.4s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.4s ease;
}

.person-card:hover .person-avatar {
    filter: grayscale(0);
    transform: scale(1.06);
    border-color: var(--ink);
}

.person-name {
    font-size: 0.78rem;
    color: var(--ink);
    line-height: 1.25;
    font-family: 'Anthropic Serif', serif;
    font-weight: bold;
    max-width: 130px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.person-handle {
    font-size: 0.62rem;
    color: var(--ink-faint);
    max-width: 130px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-top: 0.15rem;
}

/* ── Footer ── */
.footer {
    border-top: 1px solid var(--line-dark);
    max-width: 1100px;
    margin: 2rem auto 0;
    padding: 1.5rem 2rem 2.5rem;
    display: flex;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
    color: var(--ink-faint);
    font-size: 0.65rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}

/* ── Responsive ── */
@media (max-width: 760px) {
    .mission { grid-template-columns: 1fr; gap: 1.75rem; }
    .featured-card { flex-direction: column; align-items: flex-start; gap: 1rem; }
}

@media (max-width: 640px) {
    .hero { padding: 3.5rem 1.25rem 2.5rem; }
    .hero-stats { grid-template-columns: 1fr; border-bottom: none; }
    .stat { border-left: none; padding-left: 0; border-bottom: 1px solid var(--line); }
    .people-grid { grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); }
    .person-avatar { width: 48px; height: 48px; }
    .section { padding: 3rem 1.25rem; }
    .topbar { padding: 1rem 1.25rem; }
}

