636	(function () {
637	    var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
638	
639	    // Tag elements for scroll-reveal, staggering grids and groups.
640	    document.querySelectorAll('.section-label, .section h2, .section-sub, .mission blockquote, .accent-line, .mission > p, .mission-goal, .footer p').forEach(function (el) {
641	        el.classList.add('reveal');
642	    });
643	    document.querySelectorAll('.people-grid').forEach(function (grid) {
644	        Array.prototype.forEach.call(grid.children, function (card, i) {
645	            card.classList.add('reveal');
646	            card.style.setProperty('--d', (Math.min(i, 24) * 0.04) + 's');
647	        });
648	    });
649	
650	    if (reduced || !('IntersectionObserver' in window)) {
651	        document.querySelectorAll('.reveal').forEach(function (el) { el.classList.add('in'); });
652	    } else {
653	        var io = new IntersectionObserver(function (entries) {
654	            entries.forEach(function (entry) {
655	                if (entry.isIntersecting) {
656	                    entry.target.classList.add('in');
657	                    io.unobserve(entry.target);
658	                }
659	            });
660	        }, { threshold: 0.12, rootMargin: '0px 0px -5% 0px' });
661	        document.querySelectorAll('.reveal').forEach(function (el) { io.observe(el); });
662	    }
663	
664	    // Count up the hero stats once they animate in.
665	    if (!reduced) {
666	        document.querySelectorAll('.stat-num').forEach(function (el) {
667	            var text = el.textContent;
668	            var match = text.match(/\d+/);
669	            if (!match) return;
670	            var target = parseInt(match[0], 10);
671	            var start = null;
672	            var duration = 1100;
673	            function tick(ts) {
674	                if (start === null) start = ts;
675	                var p = Math.min((ts - start) / duration, 1);
676	                var eased = 1 - Math.pow(1 - p, 3);
677	                el.textContent = text.replace(match[0], String(Math.round(target * eased)));
678	                if (p < 1) requestAnimationFrame(tick);
679	                else el.textContent = text;
680	            }
681	            setTimeout(function () { requestAnimationFrame(tick); }, 480);
682	        });
683	    }
684	})();
